variables.input:
timeseries { avg(crux.lcp.p75), lcp = avg(crux.lcp.p75, scalar: true) }
, by: { friendlyname }
| summarize dom=collectDistinct(friendlyname)
| expand dom
| fieldsAdd dom=replaceString(dom,"_"," ")
| sort dom

1.query:
timeseries { avg(crux.cls.p75), cls = avg(crux.cls.p75, scalar: true) }
, by: { formfactor, friendlyname }
| summarize {d=toString(collectArray(array(formfactor, cls))), totale=avg(cls)}, by: {friendlyname}
| parse d, """LD KVP{ '[' DQS:key ', ' FLOAT:value ']'', '?}:valore"""
| fieldsFlatten valore, prefix:" "
| fieldsRemove d, valore
| fieldsAdd friendlyname=replacestring(friendlyname,"_"," ")
| filter in(friendlyname,$Item)
| sort totale asc

